#!/usr/bin/env python3
"""Audit services/ against SPEC.md + amendments; write findings/svc-XX.json."""
import ast
import json
import os
import re
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
ROOT = sys.argv[1] if len(sys.argv) > 1 else ROOT
SERVICES = os.path.join(ROOT, "services")
FINDINGS = os.path.join(ROOT, "findings")
POINTER = "version https://git-lfs.github.com/spec/v1"

DIGEST = re.compile(r"@sha256:([0-9a-f]+)$")
LOWER_HEX64 = re.compile(r"^[0-9a-f]{64}$")
REQ_PIN = re.compile(r"^[A-Za-z0-9_.\-\[\]]+==[A-Za-z0-9_.\-+]+$")
HEX_DIGITS = set("0123456789abcdef")


def read(path):
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        return fh.read()


def load_config(svc):
    path = os.path.join(SERVICES, svc, "config.json")
    try:
        return json.loads(read(path))
    except (OSError, ValueError):
        return {}


def is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def is_pointer(path):
    try:
        with open(path, "rb") as fh:
            first = fh.readline()
    except OSError:
        return False
    return first.rstrip(b"\r\n").decode("utf-8", "replace") == POINTER


def service_files(svc):
    base = os.path.join(SERVICES, svc)
    for dirpath, dirnames, filenames in os.walk(base):
        dirnames.sort()
        for name in sorted(filenames):
            yield os.path.join(dirpath, name)


def py_files_under(svc, sub):
    base = os.path.join(SERVICES, svc, sub)
    out = []
    for dirpath, dirnames, filenames in os.walk(base):
        dirnames.sort()
        for name in sorted(filenames):
            if name.endswith(".py"):
                out.append(os.path.join(dirpath, name))
    return out


def parsed(path):
    try:
        return ast.parse(read(path))
    except (OSError, SyntaxError):
        return None


def check_c1(svc, cfg):
    return cfg.get("exposure") == "public" and not (
        isinstance(cfg.get("timeout_s"), (int, float))
        and not isinstance(cfg.get("timeout_s"), bool)
        and cfg["timeout_s"] <= 30
    )


def check_c2(svc, cfg):
    tree = parsed(os.path.join(SERVICES, svc, "src", "handlers.py"))
    if tree is None:
        return True
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name.startswith("handle_"):
            if ast.get_docstring(node) is None:
                return True
    return False


def check_c3(svc, cfg):
    for path in py_files_under(svc, "src"):
        tree = parsed(path)
        if tree is None:
            return True
        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                func = node.func
                if isinstance(func, ast.Name) and func.id == "print":
                    return True
    return False


def check_c4(svc, cfg):
    retries = cfg.get("retries")
    return not (is_int(retries) and 1 <= retries <= 5)


def check_c5(svc, cfg):
    path = os.path.join(SERVICES, svc, "Dockerfile")
    if not os.path.isfile(path):
        return True
    for raw in read(path).splitlines():
        line = raw.strip()
        if not line or not line.upper().startswith("FROM "):
            continue
        tokens = [t for t in line.split() if not t.startswith("--")]
        image = tokens[1] if len(tokens) > 1 else ""
        match = DIGEST.search(image)
        if not match or not LOWER_HEX64.match(match.group(1)):
            return True
    return False


def check_c6(svc, cfg):
    path = os.path.join(SERVICES, svc, "Dockerfile")
    if not os.path.isfile(path):
        return True
    user = None
    for raw in read(path).splitlines():
        line = raw.strip()
        if line.upper().startswith("USER "):
            user = line.split(None, 1)[1].strip()
    if not user:
        return True
    principal = user.split(":")[0].strip().lower()
    return principal in ("root", "0")


def check_c7(svc, cfg):
    path = os.path.join(SERVICES, svc, "README.md")
    if not os.path.isfile(path):
        return True
    return "## Runbook" not in read(path).splitlines()


def check_c8(svc, cfg):
    path = os.path.join(SERVICES, svc, "CODEOWNERS")
    if not os.path.isfile(path):
        return True
    team = cfg.get("team")
    if not isinstance(team, str) or not team:
        return True
    wanted = "@team-" + team
    for raw in read(path).splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        if parts[0] == "*" and wanted in parts[1:]:
            return False
    return True


def check_c9(svc, cfg):
    for path in py_files_under(svc, "src"):
        tree = parsed(path)
        if tree is None:
            return True
        for node in ast.walk(tree):
            if isinstance(node, ast.Constant) and isinstance(node.value, str):
                if node.value.startswith("sk_live_") or node.value.startswith("AKIA"):
                    return True
    return False


def check_c10(svc, cfg):
    healthcheck = cfg.get("healthcheck")
    if not isinstance(healthcheck, str) or not healthcheck:
        return True
    segment = healthcheck.split("?", 1)[0].rstrip("/").rsplit("/", 1)[-1]
    handler = "handle_" + segment
    tree = parsed(os.path.join(SERVICES, svc, "src", "handlers.py"))
    if tree is None:
        return True
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == handler:
            return False
    return True


def check_c11(svc, cfg):
    return cfg.get("metrics_port") == cfg.get("port") or "metrics_port" not in cfg or "port" not in cfg


def check_c12(svc, cfg):
    path = os.path.join(SERVICES, svc, "requirements.txt")
    if not os.path.isfile(path):
        return True
    for raw in read(path).splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        line = re.split(r"\s+#", line, 1)[0].strip()
        if not REQ_PIN.match(line):
            return True
    return False


def check_c13(svc, cfg):
    return cfg.get("log_level") == "DEBUG"


def check_c14(svc, cfg):
    if cfg.get("exposure") != "public":
        return False
    value = cfg.get("max_body_kb")
    return not (is_int(value) and value <= 1024)


def check_c15(svc, cfg):
    base = os.path.join(SERVICES, svc, "tests")
    if not os.path.isdir(base):
        return True
    for dirpath, dirnames, filenames in os.walk(base):
        for name in filenames:
            if name.startswith("test_") and name.endswith(".py"):
                return False
    return True


def check_c16(svc, cfg):
    if cfg.get("exposure") != "public":
        return False
    value = cfg.get("rate_limit_rps")
    return not (is_int(value) and 1 <= value <= 10000)


CHECKS = [
    ("C1", check_c1),
    ("C2", check_c2),
    ("C3", check_c3),
    ("C4", check_c4),
    ("C5", check_c5),
    ("C6", check_c6),
    ("C7", check_c7),
    ("C8", check_c8),
    ("C9", check_c9),
    ("C10", check_c10),
    ("C11", check_c11),
    ("C12", check_c12),
    ("C13", check_c13),
    ("C14", check_c14),
    ("C15", check_c15),
    ("C16", check_c16),
]


def main():
    os.makedirs(FINDINGS, exist_ok=True)
    services = sorted(
        name for name in os.listdir(SERVICES)
        if os.path.isdir(os.path.join(SERVICES, name))
    )
    for svc in services:
        if any(is_pointer(path) for path in service_files(svc)):
            report = {"service": svc, "status": "unverifiable", "violations": []}
        else:
            cfg = load_config(svc)
            violations = [cid for cid, check in CHECKS if check(svc, cfg)]
            status = "violations" if violations else "compliant"
            report = {"service": svc, "status": status, "violations": violations}
        with open(os.path.join(FINDINGS, svc + ".json"), "w", encoding="utf-8") as fh:
            json.dump(report, fh, ensure_ascii=False)
            fh.write("\n")


if __name__ == "__main__":
    main()

